class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        # l 指向下一个写入位置：nums[0..l) 是「每元素最多两次」的合法结果区
        # r 是读指针：r 无条件前进，l 只在保留元素时前进，速度差即删除个数
        l, r = 0, 0
        while r < len(nums):
            # l < 2：结果区还不满两个，保留必然合法
            # nums[l-2] != nums[r]：与结果区倒数第二个比较，相同则写入就是第 3 个连续重复
            if l < 2 or nums[l - 2] != nums[r]:
                nums[l] = nums[r]   # 覆盖写入，天然保持相对顺序
                l += 1
            r += 1                  # 易错点：r 必须在分支外前进，被跳过的元素不写回
        return l                    # l 恰好是保留后的新长度

