def removeElement_swap(nums, val):
    # 对撞双指针：l 找「该删的洞」，r 从尾部提供替补
    # 题目允许改变顺序，才有资格用这种「尾部填坑」写法
    l, r = 0, len(nums) - 1
    while l <= r:
        if nums[l] != val:
            l += 1                  # 保留，左指针右移
        else:
            nums[l] = nums[r]       # 尾部元素覆盖洞口
            r -= 1                  # 易错点：l 不动！替补可能也等于 val
    return l                        # [0, l) 全是保留元素，l 即新长度

