	// 有序数组中相同元素必然相邻，所以只需和「去重区末尾」比较一次
	l := 0
	for r := 1; r < n; r++ {
		if nums[r] != nums[l] {
			l++ // 发现新值，去重区扩一格
			nums[l] = nums[r] // 把新值写入扩出来的位置
		}
		// r 无条件前进，重复值直接跳过
	}
	return l + 1 // 易错点：返回长度 l+1，不是下标 l
