class Solution {
public:
    int hIndex(vector<int>& citations) {
        int n = (int)citations.size();
        // h 的上限是 n：被引 100 次的论文，在「至少 n+1 篇引用 >= n+1」时也只有 1 篇，帮不上忙
        // cnt[v] = 引用次数恰为 v 的论文篇数（超过 n 的统一记到 n，值域由此被封顶）
        vector<int> cnt(n + 1, 0);
        for (int c : citations) ++cnt[min(c, n)];   // 截断：引用数 > n 的在统计上等价于 n
        int total = 0;                  // total = 引用次数 >= h 的论文篇数
        for (int h = n; h >= 0; --h) {  // 从大到小枚举 h，找最大可行值
            total += cnt[h];            // 把「恰好 h 次」并入「>= h 次」的累计
            if (total >= h) return h;   // 易错点：条件是 >= h（至少 h 篇），不是 == h
        }
        return 0;                       // h=0 恒成立，此行只为语法完整
    }
};

