class Solution:
    def productExceptSelf(self, nums: List[int]) -> List[int]:
        n = len(nums)
        # dp[i] 先充当「前缀乘积表」：dp[i] = nums[0..i-1] 的乘积（不含自身）
        dp = [1] * n
        for i in range(1, n):
            dp[i] = dp[i - 1] * nums[i - 1]   # 递推：左侧全部元素的乘积
        right = 1                 # right = i 右侧所有元素的后缀乘积，滚动维护
        for i in range(n - 1, -1, -1):
            dp[i] *= right        # 合成：左乘积 × 右乘积 = 除自身外的乘积
            right *= nums[i]      # 易错点：先使用再自乘，保证 right 始终不含 nums[i]
        return dp

